document.addEventListener("app:route-changed",()=>{const e=[...document.querySelectorAll(".journey-bookmark-btn")];const t=[...document.querySelectorAll(".augustoffer-node")],i=document.getElementById("augustoffer-detail-eyebrow"),o=document.getElementById("augustoffer-detail-title"),n=document.getElementById("augustoffer-detail-desc"),a=document.getElementById("augustoffer-detail-verdict"),r={congress:{eyebrow:"Indian National Congress",title:"Congress Rejects the Offer",desc:"Meeting in September 1940, the Congress Working Committee rejected the August Offer. It conceded no real power during the war, offered Dominion Status rather than complete independence, and the enlarged Executive Council remained an advisory body with the Viceroy still controlling defence, finance, and foreign affairs. For Congress, the offer was a promise of freedom without any of its substance.",verdict:"Rejected — a promise of freedom, not freedom"},league:{eyebrow:"All-India Muslim League",title:"The League Welcomes It",desc:"Jinnah and the Muslim League welcomed the August Offer. The clause giving 'full weight' to minority interests was read as official recognition that Muslims were a separate political nation, and the constitution-making body's qualification of 'principal elements' seemed to protect the League's veto over any settlement. The offer legitimised the League's claim — though it still fell short of an explicit commitment to Pakistan.",verdict:"Welcomed — recognition of the League's claims"},gandhi:{eyebrow:"Mahatma Gandhi",title:"Gandhi's Objection",desc:"Gandhi saw the offer as widening the gulf between Congress and Britain rather than closing it. Since it transferred no real responsibility to Indians during the war, it was, in effect, no offer at all. He counselled Congress against acceptance, and after the rejection he designed Individual Satyagraha — a limited, symbolic assertion of free speech against war participation that kept the struggle alive without imperilling Britain under Axis attack.",verdict:"Objected — the offer gave nothing real"},british:{eyebrow:"London & New Delhi",title:"Britain's Aims",desc:"The British government's political objectives were practical: secure India's full cooperation in a war Britain was losing in 1940, reassure Allied opinion (especially the United States), and keep the Muslim League onside by protecting minority interests. The offer was designed to concede a future goal while preserving all immediate power in the Viceroy's hands.",verdict:"Offered a goal, kept the power"}};t.forEach(e=>{e.addEventListener("click",()=>function(e){const s=r[e];s&&(t.forEach(t=>{const i=t.dataset.party===e;t.classList.toggle("active",i),t.setAttribute("aria-pressed",String(i))}),i.textContent=s.eyebrow,o.textContent=s.title,n.textContent=s.desc,a.textContent=s.verdict)}(e.dataset.party))});const s=[...document.querySelectorAll(".augustoffer-filter-btn")],l=[...document.querySelectorAll(".augustoffer-timeline-step")];s.forEach(e=>{e.addEventListener("click",()=>{const t=e.dataset.phase;s.forEach(t=>{const i=t===e;t.classList.toggle("active",i),t.setAttribute("aria-pressed",String(i))}),l.forEach(e=>{const i="all"===t||e.dataset.phase===t;e.classList.toggle("is-filtered-out",!i)})})}),window.Journey&&(e.forEach(e=>{const t=e.dataset.bookmarkId,i=()=>{const i=window.Journey.isSaved(t);e.classList.toggle("is-saved",i),e.setAttribute("aria-pressed",String(i)),e.innerHTML=i?"♥ Saved to Journey":"♡ Save to Journey"};i(),e.addEventListener("click",e=>{e.stopPropagation(),window.Journey.toggle({id:t,explorerPage:"frontend/august-offer-1940-explorer/index.html",title:"August Offer 1940 Explorer",thumbnail:"frontend/assets/travel_deserts.png",category:"history"}),i()})}),window.Journey.registerSearchItems("frontend/august-offer-1940-explorer/index.html",[{id:"august-offer-1940-main",title:"August Offer 1940 Explorer",description:"The August Offer of 8 August 1940 — Britain's wartime promise of Dominion Status, the Congress rejection, the Muslim League's welcome, and the launch of Individual Satyagraha.",link:"frontend/august-offer-1940-explorer/index.html"},{id:"august-offer-1940-proposals",title:"The Main Proposals of the August Offer",description:"Dominion Status as the objective, a future constitution-making body, an expanded Executive Council, and a minority veto — the four clauses of the August Offer of 1940.",link:"frontend/august-offer-1940-explorer/index.html#proposals"},{id:"august-offer-1940-responses",title:"Responses to the August Offer",description:"Congress rejected the offer, the Muslim League welcomed it, and Gandhi called for Individual Satyagraha — the responses that followed the August Offer of 1940.",link:"frontend/august-offer-1940-explorer/index.html#responses"},{id:"august-offer-1940-timeline",title:"August Offer 1940 Political Timeline",description:"From the outbreak of the Second World War and the Lahore Resolution to the August Offer, the Congress rejection, and Individual Satyagraha.",link:"frontend/august-offer-1940-explorer/index.html#timeline"}]))});